3	/**
4	 * Derives an owner's locality (region) from their city using a fixed
5	 * city-to-region table (Sydney -> NSW, Melbourne -> VIC, Brisbane -> QLD).
6	 *
7	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper})
8	 * so MapStruct does not mistake it for a generic {@code String -> String}
9	 * mapping method and apply it to unrelated fields; the mapper references it only
10	 * through an explicit expression.
11	 */
12	public final class LocalityDeriver {
13	
14	    private LocalityDeriver() {
15	    }
16	
17	    /**
18	     * Returns the canonical region string for the given city, or {@code "UNKNOWN"}
19	     * when the city is {@code null} or not in the fixed table.
20	     */
21	    public static String locality(String city) {
22	        if (city == null) {
23	            return "UNKNOWN";
24	        }
25	        return switch (city) {
26	            case "Sydney" -> "NSW";
27	            case "Melbourne" -> "VIC";
28	            case "Brisbane" -> "QLD";
29	            default -> "UNKNOWN";
30	        };
31	    }
32	}
