93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
