127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        if (isBlank(ownerFieldsDto.getFirstName())) {
132	            missingFields.add("firstName");
133	        }
134	        if (isBlank(ownerFieldsDto.getLastName())) {
135	            missingFields.add("lastName");
136	        }
137	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
138	        if (isBlank(normalizedAddress)) {
139	            missingFields.add("address");
140	        }
141	        if (isBlank(ownerFieldsDto.getCity())) {
142	            missingFields.add("city");
143	        }
144	        if (isBlank(ownerFieldsDto.getTelephone())) {
145	            missingFields.add("telephone");
146	        }
147	        if (!missingFields.isEmpty()) {
148	            throw new MissingOwnerFieldsException(missingFields);
149	        }
150	        LocalDate registrationDate = toBusinessDay(
151	            ownerFieldsDto.getRegistrationDate() != null
152	                ? ownerFieldsDto.getRegistrationDate()
153	                : LocalDate.now());
154	        long registeredOnDay = this.clinicService.findAllOwners().stream()
155	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
156	            .count();
157	        if (registeredOnDay >= 100) {
158	            throw new DailyRegistrationLimitException(
159	                "100 or more owners have already been registered today");
160	        }
161	        boolean bulkSignupWarning = registeredOnDay > 80;
162	        String city = ownerFieldsDto.getCity();
163	        long ownersInCity = this.clinicService.findAllOwners().stream()
164	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
165	            .count();
166	        if (ownersInCity >= 50) {
167	            throw new CityAtCapacityException(
168	                "the owner's city already contains 50 or more owners");
169	        }
170	        ownerFieldsDto.setAddress(normalizedAddress);
171	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
172	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
173	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
174	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
175	            .toList();
176	        String householdId = null;
177	        if (!householdMembers.isEmpty()) {
178	            // Owners sharing a normalized last name and address form a household with a
179	            // stable shared identifier; backfill any members created before it was formed.
180	            // The household id is part of the identity key, so two members with different
181	            // telephones have different identity keys and are both allowed.
182	            householdId = householdId(lastName, normalizedAddress);
183	            for (Owner member : householdMembers) {
184	                if (!householdId.equals(member.getHouseholdId())) {
185	                    member.setHouseholdId(householdId);
186	                    this.clinicService.saveOwner(member);
187	                }
188	            }
189	        }
190	        String telephone = toE164(ownerFieldsDto.getTelephone());
191	        ownerFieldsDto.setTelephone(telephone);
192	        String email = normalizeEmail(ownerFieldsDto.getEmail());
193	        ownerFieldsDto.setEmail(email);
194	        // Single, consolidated duplicate check: reject only when the new owner's whole
195	        // derived identity key (telephone|email|householdId) equals an existing owner's.
196	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
197	        boolean identityInUse = this.clinicService.findAllOwners().stream()
198	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
199	                existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
200	        if (identityInUse) {
201	            throw new DuplicateIdentityException(
202	                "an owner with the same identity key already exists");
203	        }
204	        HttpHeaders headers = new HttpHeaders();
205	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
206	        owner.setRegistrationDate(registrationDate);
207	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
208	        owner.setHouseholdId(householdId);
209	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
210	        owner.setBulkSignupWarning(bulkSignupWarning);
211	        // Household size after this create: existing members plus the owner being created.
212	        owner.setHouseholdSize(householdMembers.size() + 1);
213	        this.clinicService.saveOwner(owner);
214	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
215	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
216	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
217	            ownerDto.getMembershipLevel());
218	        headers.setLocation(UriComponentsBuilder.newInstance()
219	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
220	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
221	    }
