227	        if (currentOwner == null) {
228	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	        }
230	        currentOwner.setAddress(ownerFieldsDto.getAddress());
231	        currentOwner.setCity(ownerFieldsDto.getCity());
232	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
233	        currentOwner.setLastName(ownerFieldsDto.getLastName());
234	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
235	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
236	        this.clinicService.saveOwner(currentOwner);
237	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
238	    }
