316	
317	    private static boolean isBlank(String value) {
318	        return value == null || value.isBlank();
319	    }
320	
321	    /**
322	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
323	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
324	     * to the effective registration date (whether supplied in the request or defaulted to the server
325	     * date), so every value derived from the registration date sees the adjusted business day.
326	     */
327	    private static LocalDate toBusinessDay(LocalDate date) {
328	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
329	            date = date.plusDays(1);
330	        }
331	        return date;
332	    }
333	
334	    /**
335	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
336	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
337	     * lower-cased so that last names are compared case-insensitively.
338	     */
339	    private static String normalizeHousehold(String value) {
340	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
341	    }
342	
343	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
344	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
345	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
346	
347	    /**
348	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
349	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
350	     * upper-cased, and common street-type abbreviations are expanded token-by-token
351	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
352	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
353	     * used for every address comparison (household-duplicate detection and the shared household id).
354	     */
355	    private static String normalizeAddress(String value) {
356	        if (value == null) {
357	            return "";
358	        }
359	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
360	        if (collapsed.isEmpty()) {
361	            return "";
362	        }
363	        String[] tokens = collapsed.split(" ");
364	        StringBuilder sb = new StringBuilder();
365	        for (int i = 0; i < tokens.length; i++) {
366	            if (i > 0) {
367	                sb.append(' ');
368	            }
369	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
370	        }
371	        return sb.toString();
372	    }
373	
374	    /**
375	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
376	     * deterministic function of the normalized last name and address, so every owner that
377	     * shares those values maps to the same identifier regardless of creation order.
378	     */
379	    private static String householdId(String normalizedLastName, String normalizedAddress) {
380	        String key = normalizedLastName + "\n" + normalizedAddress;
381	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
382	    }
383	
384	    /**
385	     * Builds the {@code customerCode} assigned to a new owner, formatted
386	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
387	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
388	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
389	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
390	     */
391	    private String nextCustomerCode(String city, String lastName) {
392	        String city3 = prefix3(city);
393	        String last3 = prefix3(lastName);
394	        long sequence = this.clinicService.findAllOwners().stream()
395	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
396	            .count() + 1L;
397	        return String.format("%s-%s-%04d", city3, last3, sequence);
398	    }
399	
400	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
401	    private static String prefix3(String value) {
402	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
403	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
404	    }
405	
406	    /**
407	     * Counts the existing owners that share the given first name and last name, compared
408	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
409	     * owner currently being created is saved), so it reflects how many namesakes preceded the
410	     * new owner.
411	     */
412	    private int countNamesakes(String firstName, String lastName) {
413	        return (int) this.clinicService.findAllOwners().stream()
414	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
415	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
416	            .count();
417	    }
418	
419	    /**
420	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
421	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
422	     * national one, a single leading {@code '0'} is dropped, and the default country code
423	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
424	     * national number must have the length required by its country code ({@code '+61'} requires 9
425	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
426	     * raised (reported to the client as 400).
427	     */
428	    private static String toE164(String telephone) {
429	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
430	        String digits;
431	        if (cleaned.startsWith("+")) {
432	            digits = cleaned.substring(1);
433	        } else {
434	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
435	            digits = "61" + national;
436	        }
437	        if (!digits.matches("[0-9]{8,15}")) {
438	            throw new InvalidTelephoneException(
439	                "telephone must form a valid E.164 number with 8 to 15 digits");
440	        }
441	        validateNationalLength(digits);
442	        return "+" + digits;
443	    }
444	
445	    /** National-number length required for each supported country code (digits after the code). */
446	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
447	        "61", 9, "1", 10);
448	
449	    /**
450	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
451	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
452	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
453	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
454	     */
455	    private static void validateNationalLength(String digits) {
456	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
457	            String code = entry.getKey();
458	            if (digits.startsWith(code)) {
459	                int nationalLength = digits.length() - code.length();
460	                if (nationalLength != entry.getValue()) {
461	                    throw new InvalidTelephoneException(
462	                        "telephone national number must have " + entry.getValue()
463	                            + " digits for country code +" + code);
464	                }
465	                return;
466	            }
467	        }
468	    }
469	
470	    /**
471	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
472	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
473	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
474	     * stored and returned in canonical form.
475	     */
476	    private static String normalizeEmail(String email) {
477	        if (isBlank(email)) {
478	            return null;
479	        }
480	        String trimmed = email.trim();
481	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
482	            throw new InvalidEmailException("email must be a syntactically valid address");
483	        }
484	        return trimmed.toLowerCase(Locale.ROOT);
485	    }
486	}
